package com.raceforge.backend.training.service;
import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.time.*;import java.util.*;
class PackageRoadmapDefaultsTest {
 @Test void packageDefaultsAreDistinctAndBounded(){var p=new PackageRoadmapPolicy();Map<String,Integer> minutes=Map.of("BASIC",30,"RACING",40,"PERFORMANCE",35,"RECOVERY",20);Map<String,Set<DayOfWeek>> days=Map.of("BASIC",Set.of(DayOfWeek.MONDAY,DayOfWeek.WEDNESDAY,DayOfWeek.FRIDAY),"RECOVERY",Set.of(DayOfWeek.MONDAY,DayOfWeek.WEDNESDAY,DayOfWeek.FRIDAY),"RACING",Set.of(DayOfWeek.MONDAY,DayOfWeek.TUESDAY,DayOfWeek.THURSDAY,DayOfWeek.SATURDAY),"PERFORMANCE",Set.of(DayOfWeek.MONDAY,DayOfWeek.WEDNESDAY,DayOfWeek.FRIDAY,DayOfWeek.SATURDAY));Set<String> activities=new HashSet<>();for(String type:minutes.keySet()){var stages=p.suggestedStages(p.template(type,30));TrainingRecommendationService.validateStages(stages,30);assertEquals(1,stages.get(0).startDay());assertEquals(30,stages.get(stages.size()-1).endDay());for(var stage:stages){assertEquals(days.get(type),stage.daysOfWeek());assertEquals(minutes.get(type).longValue(),Duration.between(stage.sessionTime(),stage.sessionEndTime()).toMinutes());assertEquals(LocalTime.of(7,0),stage.sessionTime());assertEquals("LOW",stage.intensity());assertTrue(activities.add(stage.activityName()));}}}
 @Test void trainerSelectedIntensityIsPreserved(){var p=new PackageRoadmapPolicy();var s=new com.raceforge.backend.training.dto.TrainingWorkflowDtos.Stage(1,30,"Custom","HIGH",Set.of(DayOfWeek.TUESDAY),LocalTime.of(9,0),LocalTime.of(9,40));assertTrue(p.apply("RACING",List.of(s),30).stream().allMatch(part->part.activity().intensity().equals("HIGH")&&part.activity().sessionTime().equals(LocalTime.of(9,0))));}
 @Test void shortPackageStaysWithinItsDates(){var p=new PackageRoadmapPolicy();var stages=p.suggestedStages(p.template("RACING",1));assertEquals(1,stages.size());assertEquals(1,stages.get(0).endDay());}
}
